300  static void
   301  gvs_fixed_sized_maybe_serialise (GVariantSerialised        value,
   302                                   GVariantSerialisedFiller  gvs_filler,
   303                                   const gpointer           *children,
   304                                   gsize                     n_children)
   305  {
   306    if (n_children)
   307      {
   308        GVariantSerialised child = { NULL, value.data, value.size, value.depth + 1, 0, 0 };
   309
   310        gvs_filler (&child, children[0]);
   311      }
   312  }
   313
   314  static gboolean
   315  gvs_fixed_sized_maybe_is_normal (GVariantSerialised value)
   316  {
   317    if (value.size > 0)
   318      {
   319        gsize element_fixed_size;
   320
   321        g_variant_type_info_query_element (value.type_info,
   322                                           NULL, &element_fixed_size);
   323
   324        if (value.size != element_fixed_size)
   325          return FALSE;
   326
   327        /* proper element size: "Just".  recurse to the child. */
   328        value.type_info = g_variant_type_info_element (value.type_info);
   329        value.depth++;
   330        value.ordered_offsets_up_to = 0;
   331        value.checked_offsets_up_to = 0;
   332
   333        return g_variant_serialised_is_normal (value);
   334      }
   335
   336    /* size of 0: "Nothing" */
   337    return TRUE;
   338  }
