   379  static gsize
   380  gvs_variable_sized_maybe_needed_size (GVariantTypeInfo         *type_info,
   381                                        GVariantSerialisedFiller  gvs_filler,
   382                                        const gpointer           *children,
   383                                        gsize                     n_children)
   384  {
   385    if (n_children)
   386      {
   387        GVariantSerialised child = { 0, };
   388
   389        gvs_filler (&child, children[0]);
   390
   391        return child.size + 1;
   392      }
   393    else
   394      return 0;
   395  }
