   413  static gboolean
   414  gvs_variable_sized_maybe_is_normal (GVariantSerialised value)
   415  {
   416    if (value.size == 0)
   417      return TRUE;
   418
   419    if (value.data[value.size - 1] != '\0')
   420      return FALSE;
   421
   422    value.type_info = g_variant_type_info_element (value.type_info);
   423    value.size--;
   424    value.depth++;
   425    value.ordered_offsets_up_to = 0;
   426    value.checked_offsets_up_to = 0;
   427
   428    return g_variant_serialised_is_normal (value);
   429  }
