   431  /* Arrays {{{2
   432   *
   433   * Just as with maybe types, array types are handled depending on if the
   434   * element type of the array type is a fixed-sized or variable-sized
   435   * type.  Similar to maybe types, for convenience, an array value with a
   436   * fixed-sized element type is called a "fixed-sized array" and an array
   437   * value with a variable-sized element type is called a "variable sized
   438   * array".
   439   */
   440
   441  /* Fixed-sized Array {{{3
   442   *
   443   * For fixed sized arrays, the serialized data is simply a concatenation
   444   * of the serialized data of each element, in order.  Since fixed-sized
   445   * values always have a fixed size that is a multiple of their alignment
   446   * requirement no extra padding is required.
   447   *
   448   * In the event that a fixed-sized array is presented with a size that
   449   * is not an integer multiple of the element size then the value of the
   450   * array must be taken as being empty.
   451   */
   452
   453  static gsize
   454  gvs_fixed_sized_array_n_children (GVariantSerialised value)
   455  {
   456    gsize element_fixed_size;
   457
   458    g_variant_type_info_query_element (value.type_info, NULL,
   459                                       &element_fixed_size);
   460
   461    if (value.size % element_fixed_size == 0)
   462      return value.size / element_fixed_size;
   463
   464    return 0;
   465  }
   466
   467  static GVariantSerialised
   468  gvs_fixed_sized_array_get_child (GVariantSerialised value,
   469                                   gsize              index_)
   470  {
   471    GVariantSerialised child = { 0, };
   472
   473    child.type_info = g_variant_type_info_element (value.type_info);
   474    g_variant_type_info_query (child.type_info, NULL, &child.size);
   475    child.data = value.data + (child.size * index_);
   476    g_variant_type_info_ref (child.type_info);
   477    child.depth = value.depth + 1;
   478
   479    return child;
   480  }
   481
   482  static gsize
   483  gvs_fixed_sized_array_needed_size (GVariantTypeInfo         *type_info,
   484                                     GVariantSerialisedFiller  gvs_filler,
   485                                     const gpointer           *children,
   486                                     gsize                     n_children)
   487  {
   488    gsize element_fixed_size;
   489
   490    g_variant_type_info_query_element (type_info, NULL, &element_fixed_size);
   491
   492    return element_fixed_size * n_children;
   493  }
   494
   495  static void
   496  gvs_fixed_sized_array_serialise (GVariantSerialised        value,
   497                                   GVariantSerialisedFiller  gvs_filler,
   498                                   const gpointer           *children,
   499                                   gsize                     n_children)
   500  {
   501    GVariantSerialised child = { 0, };
   502    gsize i;
   503
   504    child.type_info = g_variant_type_info_element (value.type_info);
   505    g_variant_type_info_query (child.type_info, NULL, &child.size);
   506    child.data = value.data;
   507    child.depth = value.depth + 1;
   508
   509    for (i = 0; i < n_children; i++)
   510      {
   511        gvs_filler (&child, children[i]);
   512        child.data += child.size;
   513      }
   514  }
   515
   516  static gboolean
   517  gvs_fixed_sized_array_is_normal (GVariantSerialised value)
   518  {
   519    GVariantSerialised child = { 0, };
   520
   521    child.type_info = g_variant_type_info_element (value.type_info);
   522    g_variant_type_info_query (child.type_info, NULL, &child.size);
   523    child.depth = value.depth + 1;
   524
   525    if (value.size % child.size != 0)
   526      return FALSE;
   527
   528    for (child.data = value.data;
   529         child.data < value.data + value.size;
   530         child.data += child.size)
   531      {
   532        if (!g_variant_serialised_is_normal (child))
   533          return FALSE;
   534      }
   535
   536    return TRUE;
   537  }
